package net.saksolm.monsterexpansion.item;

import java.util.function.Consumer;
import net.minecraft.client.renderer.BlockEntityWithoutLevelRenderer;
import net.minecraft.world.item.Item;
import net.minecraft.world.item.Tier;
import net.minecraftforge.client.extensions.common.IClientItemExtensions;
import net.saksolm.monsterexpansion.item.GreatSwordActionItem;
import net.saksolm.monsterexpansion.item.client.GreatSwordRenderer;

public class GreatSwordItem
extends GreatSwordActionItem {
    public GreatSwordItem(Tier tier, int attackDamageModifier, float attackSpeedModifier, Item.Properties properties) {
        super(tier, attackDamageModifier, attackSpeedModifier, properties);
    }

    public void initializeClient(Consumer<IClientItemExtensions> consumer) {
        consumer.accept(new IClientItemExtensions(){
            private GreatSwordRenderer renderer;

            public BlockEntityWithoutLevelRenderer getCustomRenderer() {
                if (this.renderer == null) {
                    this.renderer = new GreatSwordRenderer();
                }
                return this.renderer;
            }
        });
    }
}

